pts=[(2,6),(2,12),(3,13),(4,13),(5,6),(5,7),(5,8),(5,10),(5,11),(5,12),(7,6),(8,13),(10,6),(10,12),(10,13)]
for r,c in pts:g[r][c]=4
for r in range(12):
 cs=[c for rr,c in pts if rr==r]
 if cs:
  for c in range(min(cs),max(cs)+1):
   if g[r][c]==8:g[r][c]=2
for c in range(18):
 rs=[r for r,cc in pts if cc==c]
 if rs:
  for r in range(min(rs),max(rs)+1):
   if g[r][c]==8:g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g));print([len(x) for x in g])
